#!/usr/bin/env bash
# Blind checkpoint — twine-src session twine-take-read (Arc 1, session 2a), v1.
# Authored at sitting 2026-09-29-begin-harness-001 from the request alone,
# before any implementation exists (TARBALL.md 7; PLANNER.md 4). Outcome
# contracts only. cwd = the staged tree, confined, network off.
# Exit 0 pass; 1 a probe failed (HOLD); 2 this script is broken.
#
# The specimens below are real emitter bytes: a probe block the sitting
# sent, the architect's paste of its output (CRLF as the chat delivered
# it), a light block and an exchange block rendered by bale 0.4.45's
# crafter, and the architect's paste of a `bale apply` ratification
# relay. Variants (truncated, tampered, CRLF) are derived mechanically.
# Writes: one private temp directory (mktemp -d), removed on exit.

set -u
export PYTHONDONTWRITEBYTECODE=1
fails=0
pass() { echo "[PASS] $1"; }
fail() { echo "[FAIL] $1"; fails=$((fails + 1)); }
self_error() { echo "[ERROR] checkpoint: $1"; exit 2; }
command -v python3 >/dev/null 2>&1 || self_error "python3 not found on PATH"
TMP="$(mktemp -d 2>/dev/null || true)"
[ -n "$TMP" ] && [ -d "$TMP" ] || { TMP="./.checkpoint-tmp.$$"; mkdir -p "$TMP" || self_error "cannot create a temp dir"; }
trap 'rm -rf "$TMP"' EXIT
echo "checkpoint twine-take-read v1: temp dir $TMP (removed on exit); tree writes: none"

SPEC_B64=''
mkdir -p "$TMP/s"
printf '%s' "$SPEC_B64" | base64 -d | tar -xzf - -C "$TMP/s" 2>/dev/null || self_error "could not unpack the embedded specimens"
[ -f "$TMP/s/t-relay.txt" ] || self_error "specimens incomplete"
sed -i "s|@CANARY@|$TMP/canary.touched|" "$TMP/s/t-canary.txt"

# judge.py OUT ERR CODE EXPR LABEL: one JSON line on stdout, no traceback,
# and EXPR (python over the parsed object o and the exit code rc) true.
cat > "$TMP/judge.py" <<'PYEOF'
import json, sys
out, err, rc, expr, label = sys.argv[1], sys.argv[2], int(sys.argv[3]), sys.argv[4], sys.argv[5]
def verdict(ok):
    print(("[PASS] " if ok else "[FAIL] ") + label)
try:
    data = open(out, "rb").read().decode("utf-8")
    errtext = open(err, "rb").read().decode("utf-8", "replace")
    lines = data.split("\n")
    if len(lines) != 2 or lines[1] != "":
        verdict(False); sys.exit(0)
    o = json.loads(lines[0])
    if not isinstance(o, dict) or o.get("command") != "take" or not isinstance(o.get("ok"), bool):
        verdict(False); sys.exit(0)
    if "Traceback" in errtext:
        verdict(False); sys.exit(0)
    if rc != (0 if o["ok"] else 1):
        verdict(False); sys.exit(0)
    verdict(bool(eval(expr, {"o": o, "rc": rc})))
except Exception:
    verdict(False)
PYEOF

# control: the judge rejects what it must reject, and accepts a good line.
printf '{"command": "take", "ok": true, "shape": "prose", "blocks": []}\n' > "$TMP/c1.out"; : > "$TMP/c.err"
printf '{"command": "take", "ok": true}\n{"x": 1}\n' > "$TMP/c2.out"
printf '{"command": "take", "ok": true, "shape": "prose", "blocks": []}\n' > "$TMP/c3.out"; printf 'Traceback (most recent call last):\n' > "$TMP/c3.err"
python3 "$TMP/judge.py" "$TMP/c1.out" "$TMP/c.err" 0 'o["shape"] == "prose"' c1 | grep -q '^\[PASS\]' || self_error "control: judge rejected a good line"
python3 "$TMP/judge.py" "$TMP/c2.out" "$TMP/c.err" 0 'True' c2 | grep -q '^\[FAIL\]' || self_error "control: judge accepted two lines"
python3 "$TMP/judge.py" "$TMP/c3.out" "$TMP/c3.err" 0 'True' c3 | grep -q '^\[FAIL\]' || self_error "control: judge accepted a traceback"
python3 "$TMP/judge.py" "$TMP/c1.out" "$TMP/c.err" 1 'True' c4 | grep -q '^\[FAIL\]' || self_error "control: judge accepted exit 1 with ok true"
echo "[control] judge verified"

take() {  # take NAME ARGS...: run twine take, capture to $TMP/NAME.{out,err}, echo rc
  local name="$1"; shift
  if [ -x bin/twine ]; then ./bin/twine take "$@" --json >"$TMP/$name.out" 2>"$TMP/$name.err"; echo $?
  else : >"$TMP/$name.out"; : >"$TMP/$name.err"; echo 127; fi
}
judge() {  # judge NAME RC EXPR LABEL — prints one verdict line and counts a FAIL
  local line
  line="$(python3 "$TMP/judge.py" "$TMP/$1.out" "$TMP/$1.err" "$2" "$3" "$4")"
  echo "$line"
  case "$line" in "[FAIL]"*) fails=$((fails + 1));; "[PASS]"*) ;; *) self_error "judge printed no verdict for $4";; esac
}

# ---- 1. the verb exists ----------------------------------------------------
if [ -x bin/twine ] && ./bin/twine commands --json >"$TMP/cmds.out" 2>/dev/null \
   && python3 -c 'import json,sys; o=json.loads(open(sys.argv[1]).read()); sys.exit(0 if any(c["name"]=="take" and c["json"] for c in o["commands"]) else 1)' "$TMP/cmds.out"; then
  pass "twine commands lists take with a --json twin"
else fail "twine commands lists take with a --json twin"; fi

# ---- 2. probe block -------------------------------------------------------
rc=$(take probe "$TMP/s/t-probe.txt")
judge probe "$rc" 'o["ok"] and o["shape"] == "probe" and [b["kind"] for b in o["blocks"]] == ["probe"] and o["blocks"][0]["slug"] == "begin-harness-001"' \
  "a fenced probe block: shape probe, one block, slug begin-harness-001"

rc=$(take canary "$TMP/s/t-canary.txt")
judge canary "$rc" 'o["shape"] == "probe" and o["blocks"][-1]["slug"] == "canary-001"' \
  "a second probe block parses: slug canary-001"
if [ ! -e "$TMP/canary.touched" ]; then pass "take never executes a probe it reads"
else fail "take never executes a probe it reads"; fi

# ---- 3. probe output, the architect's real CRLF paste --------------------
rc=$(take output "$TMP/s/t-output.txt")
judge output "$rc" 'o["ok"] and o["shape"] == "probe-output" and o["blocks"][-1]["slug"] == "begin-harness-001" and o["blocks"][-1]["integrity"]["ok"] is True' \
  "probe output pasted with CRLF: shape probe-output, integrity ok"

rc=$(take trunc "$TMP/s/t-output-trunc.txt")
judge trunc "$rc" 'o["ok"] is False and o["shape"] == "probe-output" and o["blocks"][-1]["integrity"]["ok"] is False' \
  "probe output missing one line: integrity not ok, ok false, exit 1"

# ---- 4. light block -------------------------------------------------------
LIGHT_EXPR='o["ok"] and o["shape"] == "light" and o["blocks"][-1]["sid"] == "2026-09-29-begin-harness-001" and len(o["blocks"][-1]["questions"]) == 3 and o["blocks"][-1]["questions"][2]["default_assumption"] == "yes, tedder-src'"'"'s pin; session 0 itself packs before bale.toml exists, so it carries none" and o["blocks"][-1]["questions"][0]["context"] == "authoring session 0 (the seed) and its brief'"'"'s provenance line" and set(o["blocks"][-1]["questions"][1]) >= {"question", "context", "default_assumption", "why_blocked"}'
rc=$(take light "$TMP/s/t-light.txt")
judge light "$rc" "$LIGHT_EXPR" "a light block: sid, three rows, the four fields by their manifest names"
rc=$(take lightcrlf "$TMP/s/t-light-crlf.txt")
judge lightcrlf "$rc" "$LIGHT_EXPR" "the same light block with CRLF line endings parses identically"

# ---- 5. exchange block ----------------------------------------------------
rc=$(take exchange "$TMP/s/t-exchange.txt")
judge exchange "$rc" 'o["ok"] and o["shape"] == "exchange" and o["blocks"][-1]["sid"] == "2026-09-29-begin-harness-001" and o["blocks"][-1]["round"] == 1 and o["blocks"][-1]["from"] == "worker" and o["blocks"][-1]["integrity"]["ok"] is True' \
  "an exchange block: sid, round 1, from worker, trailer verified"
rc=$(take tampered "$TMP/s/t-exchange-tampered.txt")
judge tampered "$rc" 'o["ok"] is False and o["shape"] == "exchange" and o["blocks"][-1]["integrity"]["ok"] is False' \
  "an exchange block with one byte changed: integrity not ok, ok false, exit 1"

# ---- 6. relay block -------------------------------------------------------
rc=$(take relay "$TMP/s/t-relay.txt")
judge relay "$rc" 'o["ok"] and o["shape"] == "relay" and [b["kind"] for b in o["blocks"]] == ["relay"] and o["blocks"][0]["sid"] == "2026-10-01-twine-seed-001" and o["blocks"][0]["to"] == "planner"' \
  "a bale apply ratification relay (CRLF): shape relay, sid, to planner, nothing inside it read as a block"

# ---- 7. prose, several blocks, stdin --------------------------------------
rc=$(take prose "$TMP/s/t-prose.txt")
judge prose "$rc" 'o["ok"] and o["shape"] == "prose" and o["blocks"] == []' "prose only: shape prose, no blocks, exit 0"
rc=$(take multi "$TMP/s/t-multi.txt")
judge multi "$rc" 'o["ok"] and [b["kind"] for b in o["blocks"]] == ["light", "probe"] and o["shape"] == "probe"' \
  "a light block then a probe block: both, in order; shape is the turn-ending one"
if [ -x bin/twine ]; then ./bin/twine take - --json < "$TMP/s/t-light.txt" >"$TMP/stdin.out" 2>"$TMP/stdin.err"; rc=$?; else rc=127; : >"$TMP/stdin.out"; : >"$TMP/stdin.err"; fi
judge stdin "$rc" 'o["shape"] == "light"' "take - reads the turn from stdin"
if [ -x bin/twine ]; then python3 -I -S -B bin/twine take "$TMP/s/t-exchange.txt" --json >"$TMP/iso.out" 2>"$TMP/iso.err"; rc=$?; else rc=127; : >"$TMP/iso.out"; : >"$TMP/iso.err"; fi
judge iso "$rc" 'o["shape"] == "exchange"' "take runs under python3 -I -S (stdlib only)"

# ---- 8. the tree ----------------------------------------------------------
if [ -d tests ] && python3 -B -m unittest discover -s tests -t . >"$TMP/t.out" 2>&1; then pass "the suite passes: python3 -B -m unittest discover -s tests -t ."
else fail "the suite passes: python3 -B -m unittest discover -s tests -t ."; fi
[ "$(sha256sum twine-seed.md 2>/dev/null | cut -d' ' -f1)" = "cabf76158430bdcb84366afc52cbea6c5662e2870e069f8375f69642cd3e164e" ] \
  && pass "twine-seed.md untouched (sha256 cabf7615…)" || fail "twine-seed.md untouched (sha256 cabf7615…)"
[ "$(sha256sum bale.toml 2>/dev/null | cut -d' ' -f1)" = "b09e9b065594c48b2eb6c1754dd19a0700a5415b14b67ac80d629294b03cfbff" ] \
  && pass "bale.toml untouched (sha256 b09e9b06…)" || fail "bale.toml untouched (sha256 b09e9b06…)"
if [ -z "$(find . -path ./.git -prune -o \( -name '*.pyc' -o -name '__pycache__' \) -print 2>/dev/null | head -n1)" ]; then
  pass "no bytecode or __pycache__ in the tree"; else fail "no bytecode or __pycache__ in the tree"; fi
if grep -q "take" claude/context/cli-contract.md 2>/dev/null; then pass "cli-contract.md names the take verb"
else fail "cli-contract.md names the take verb"; fi

echo "checkpoint twine-take-read v1: $fails probe(s) failed"
[ "$fails" -eq 0 ] && exit 0 || exit 1
